package com.hms.patients;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="patient_identifier_settings") public class PatientIdentifierSettings { @Id private UUID id; @Column(nullable=false,unique=true) private UUID tenantId; @Column(nullable=false,length=80) private String hospitalIdentifierLabel; @Column(nullable=false) private boolean hospitalIdentifierRequired; @Column(nullable=false) private boolean hospitalIdentifierVisible; @Column(length=120) private String hospitalIdentifierFormat; @Column(nullable=false) private boolean abhaEnabled; @Column(nullable=false) private boolean abhaRequired; @Column(length=1000) private String abhaConsentText; @Column(nullable=false) private OffsetDateTime updatedAt; protected PatientIdentifierSettings(){} public PatientIdentifierSettings(UUID tenantId,UpdatePatientIdentifierSettingsRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;apply(r);} public void apply(UpdatePatientIdentifierSettingsRequest r){this.hospitalIdentifierLabel=r.hospitalIdentifierLabel();this.hospitalIdentifierRequired=r.hospitalIdentifierRequired();this.hospitalIdentifierVisible=r.hospitalIdentifierVisible();this.hospitalIdentifierFormat=r.hospitalIdentifierFormat();this.abhaEnabled=r.abhaEnabled();this.abhaRequired=r.abhaRequired();this.abhaConsentText=r.abhaConsentText();this.updatedAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getHospitalIdentifierLabel(){return hospitalIdentifierLabel;} public boolean isHospitalIdentifierRequired(){return hospitalIdentifierRequired;} public boolean isHospitalIdentifierVisible(){return hospitalIdentifierVisible;} public String getHospitalIdentifierFormat(){return hospitalIdentifierFormat;} public boolean isAbhaEnabled(){return abhaEnabled;} public boolean isAbhaRequired(){return abhaRequired;} public String getAbhaConsentText(){return abhaConsentText;} }
